#include <cmath>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long double r, v;

    cin >> n >> r >> v;

    const long double pi = acosl(-1.0L);
    const long double circumference = 2.0L * pi * r;
    const long double period = circumference / v;

    cout << fixed << setprecision(6);

    for (long long i = 0; i < n; ++i) {
        long double si, fi;
        cin >> si >> fi;

        long double distance = fi - si;
        long double revolutions = floorl(distance / circumference);
        long double time = revolutions * period;
        distance -= revolutions * circumference;

        long double left = 0.0L;
        long double right = period;

        for (int iteration = 0; iteration < 100; ++iteration) {
            long double mid = (left + right) / 2.0L;
            long double covered =
                2.0L * r * sinl(mid * pi / period) + mid * v;

            if (covered >= distance)
                right = mid;
            else
                left = mid;
        }

        time += (left + right) / 2.0L;
        cout << static_cast<double>(time) << '\n';
    }

    return 0;
}

#include <iostream>
