#include <cmath>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const double PI = acos(-1.0);
    const double EPS = 1e-12;

    long long n;
    double r, v;

    cin >> n >> r >> v;

    const double circumference = 2.0 * PI * r;
    const double period = circumference / v;

    for (long long i = 0; i < n; ++i) {
        double start, finish;
        cin >> start >> finish;

        double distance = finish - start;
        double revolutions = floor(distance / circumference);
        double time = revolutions * period;
        distance -= revolutions * circumference;

        double left = 0.0;
        double right = period;

        while (right - left > EPS) {
            double mid = (left + right) / 2.0;
            double traveled = 2.0 * r * sin(mid * PI / period) + mid * v;

            if (traveled >= distance)
                right = mid;
            else
                left = mid;
        }

        cout << fixed << setprecision(6) << time + (left + right) / 2.0 << '\n';
    }

    return 0;
}

